"use client";

import React from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

export interface AuroraBackgroundProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  showRadialGradient?: boolean;
}

export function AuroraBackground({
  children,
  className,
  showRadialGradient = true,
  ...props
}: AuroraBackgroundProps) {
  return (
    <div
      className={cn(
        "relative flex flex-col w-full h-[100vh] items-center justify-center bg-background text-foreground transition-bg overflow-hidden",
        className
      )}
      {...props}
    >
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div
          className={cn(
            "filter blur-[60px] opacity-50 absolute inset-0 mix-blend-screen will-change-transform",
            "after:content-[''] after:absolute after:inset-0 after:bg-primary/20",
            "before:content-[''] before:absolute before:inset-0 before:bg-accent/30",
            showRadialGradient &&
              `[mask-image:radial-gradient(ellipse_at_100%_0%,black_10%,var(--transparent)_70%)]`
          )}
        >
          {/* Animated Blob 1 */}
          <motion.div
            animate={{
              x: ["0%", "20%", "-20%", "0%"],
              y: ["0%", "-20%", "20%", "0%"],
              scale: [1, 1.2, 0.8, 1],
            }}
            transition={{
              duration: 20,
              repeat: Infinity,
              ease: "linear",
            }}
            className="absolute -top-[20%] -left-[10%] w-[50%] h-[50%] bg-blue-500/40 rounded-full mix-blend-screen blur-[100px]"
          />

          {/* Animated Blob 2 */}
          <motion.div
            animate={{
              x: ["0%", "-20%", "20%", "0%"],
              y: ["0%", "20%", "-20%", "0%"],
              scale: [1, 0.8, 1.2, 1],
            }}
            transition={{
              duration: 25,
              repeat: Infinity,
              ease: "linear",
            }}
            className="absolute top-[20%] -right-[10%] w-[60%] h-[60%] bg-purple-500/40 rounded-full mix-blend-screen blur-[120px]"
          />

          {/* Animated Blob 3 */}
          <motion.div
            animate={{
              x: ["0%", "30%", "-30%", "0%"],
              y: ["0%", "30%", "-30%", "0%"],
              scale: [1, 1.3, 0.7, 1],
            }}
            transition={{
              duration: 30,
              repeat: Infinity,
              ease: "linear",
            }}
            className="absolute -bottom-[20%] left-[20%] w-[70%] h-[70%] bg-emerald-500/30 rounded-full mix-blend-screen blur-[100px]"
          />
        </div>
      </div>
      <div className="relative z-10">{children}</div>
    </div>
  );
}
